"""Rewrite a standard-SQL TPC-DS query the way it is found in real Hive estates.

Deterministic per query (seeded by its number): the same query always gets the same rewrite.
Every rewrite is verified on the source before it is accepted (same result as the original),
so a Hive-ified query is a faithful Hive version, not a new query.
"""

from __future__ import annotations

import random
import re

import sqlglot
from sqlglot import exp

PREAMBLES = [
    "SET hive.cli.print.header=true;\nSET mapreduce.job.reduces=8;\n",
    "USE tpcds;\nSET hive.exec.parallel=true;\n",
    "-- generated by legacy report job\nSET hive.auto.convert.join=true;\n",
    "",
]


def hiveify(sql: str, seed: int) -> str:
    rng = random.Random(seed)
    tree = sqlglot.parse_one(sql, read="duckdb")

    def rewrite(node: exp.Expression) -> exp.Expression:
        # COALESCE(a, b) -> nvl(a, b): the Hive idiom
        if isinstance(node, exp.Coalesce) and len(node.expressions) == 1 and rng.random() < 0.8:
            return exp.Anonymous(this="nvl", expressions=[node.this, node.expressions[0]])
        # SUBSTRING -> substr
        if isinstance(node, exp.Substring):
            args = [node.this, node.args["start"]] + (
                [node.args["length"]] if node.args.get("length") else []
            )
            return exp.Anonymous(this="substr", expressions=args)
        # CAST(x AS VARCHAR) -> cast(x as string)
        if isinstance(node, exp.DataType) and node.this in (
            exp.DataType.Type.VARCHAR,
            exp.DataType.Type.TEXT,
        ):
            return exp.DataType(this=exp.DataType.Type.TEXT)
        # date + INTERVAL n DAY -> date_add(date, n); date - INTERVAL -> date_sub
        if isinstance(node, exp.Add | exp.Sub) and isinstance(node.expression, exp.Interval):
            unit = (node.expression.args.get("unit") or exp.Var(this="DAY")).name.upper()
            n = node.expression.this
            if unit.startswith("DAY"):
                fn = "date_add" if isinstance(node, exp.Add) else "date_sub"
                return exp.Anonymous(this=fn, expressions=[node.this, n])
        # <> -> != (most legacy code uses !=)
        if isinstance(node, exp.NEQ):
            return node  # sqlglot prints <>; handled textually below
        return node

    tree = tree.transform(rewrite)
    # backticks on some identifiers (a common sight in Hive code written by hand)
    if rng.random() < 0.5:
        for ident in list(tree.find_all(exp.Identifier)):
            if rng.random() < 0.25 and re.fullmatch(r"[a-z_]+", ident.name):
                ident.set("quoted", True)
    out = tree.sql(dialect="hive", pretty=True)
    if rng.random() < 0.7:
        out = out.replace("<>", "!=")
    if rng.random() < 0.5:
        out = re.sub(r"\bCAST\(", "cast(", out)
    out = PREAMBLES[rng.randrange(len(PREAMBLES))] + out
    return out.strip()
